# name: fa-exp-abs-not-differentiable-test
# technique: test fallback (test_fallback recipe): the claim at instances Sage evaluates in interval arithmetic
# goal: sage_test KaluzaKlein.FourierAnalysis.TestFunctions.exp_abs_not_differentiable file "fa-exp-abs-not-differentiable-test.sage"
# description: the one-sided derivatives of e^{-a|x|} at 0 are -a and a: Sage evaluates their difference 2a > 0
SEED = 0
RI = RealIntervalField(128)
CI = ComplexIntervalField(128)
def num(e):
    try:
        return RI(e)
    except (TypeError, ValueError):
        pass
    e = SR(e)
    for f in (lambda t: t, lambda t: t.simplify_full(), lambda t: t.canonicalize_radical()):
        try:
            return RI(f(e))
        except (TypeError, ValueError):
            pass
    try:
        return CI(e)
    except (TypeError, ValueError):
        return RI(e.n(prec=256))
def side(e):
    v = num(e)
    return v
z_ = var('z_')
instances = []
CASES = [(['1', 'one_pos'], True, {'a': '1'}), (['2', '_'], False, {'a': '2'}), (['1/5', '_'], False, {'a': '1/5'})]
for values, edge, env in CASES:
    env = {k: (eval(v, globals()) if isinstance(v, str) and v.startswith('lambda') else SR(v)) for k, v in env.items()}
    scope = dict(globals()); scope.update(env)
    L = side(eval('diff(exp(a*z_), z_).subs(z_=0) - diff(exp(-a*z_), z_).subs(z_=0)', scope))
    R = side(eval('0', scope))
    if L.parent() is CI or R.parent() is CI:
        d = CI(L) - CI(R)
        L, R = RI(d.real().abs() + d.imag().abs()), RI(0)
    instances.append(oracle_instance(*values, lhs=L, rhs=R, relation='>', edge=edge))
    print(values, L, R)
